   ['అద్దకపు పత్తి వస్త్రం', 'Chintz'], ['వర్ణద్రవ్యం', 'Pigment'], ['పంట కాలం', 'Harvest season'], ['ఇతిహాసం', 'Epic'], ['జానపద', 'Folk'], ['రూపాంతరం', 'Adaptation'],
